ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS has_depth_data boolean DEFAULT false; ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS depth_type text CHECK (depth_type IN ('depth', 'disparity', 'none')); ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS is_spatial_photo boolean DEFAULT false; ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS depth_map_url text; ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS depth_near_plane_m numeric; ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS depth_far_plane_m numeric; ALTER TABLE public.tour_node_images ADD COLUMN IF NOT EXISTS camera_intrinsics jsonb; CREATE INDEX IF NOT EXISTS idx_tour_node_images_depth ON public.tour_node_images (node_id) WHERE has_depth_data = true;